#define NVEC ((int)(sizeof VEC / sizeof VEC[0]))


// delta[0..7]: the fractional hex digits of sqrt(766965), 32 bits at a time. These eight values were also recomputed with
// integer square-root arithmetic during development and agree; the known-answer vectors exercise every constant for each key length.
static const u32 DELTA[8] = { 0xc3efe9db, 0x44626b02, 0x79e27c8a, 0x78df30ec, 0x715ea49e, 0xc785da0a, 0xe04ef22a, 0xe5c40957 };

#ifndef LEA_ROT_A
#define LEA_ROT_A 9   // left rotation of the first output word of a round (the other two are right rotations by 5 and 3)
#endif

static int hexbytes(const char *s, u8 *out) {   // hex digits (spaces ignored) -> bytes; returns byte count
    int n = 0, half = 0, cur = 0;
    for (; *s; s++) {
        int d;
        if (*s >= '0' && *s <= '9') d = *s - '0'; else if (*s >= 'a' && *s <= 'f') d = *s - 'a' + 10; else continue;
        cur = cur * 16 + d;
        if (half) { out[n++] = (u8)cur; cur = 0; }
        half ^= 1;
    }
    return n;
}
static u32 rol(u32 x, int r) { r &= 31; return r ? (x << r) | (x >> (32 - r)) : x; }
static u32 ror(u32 x, int r) { return rol(x, 32 - (r & 31)); }
static u32 le32(const u8 *p) { return (u32)p[0] | (u32)p[1] << 8 | (u32)p[2] << 16 | (u32)p[3] << 24; }
static void put_le32(u8 *p, u32 v) { p[0] = (u8)v; p[1] = (u8)(v >> 8); p[2] = (u8)(v >> 16); p[3] = (u8)(v >> 24); }

typedef struct { int rounds; u32 rk[32][6]; } lea_ctx;

static void lea_setkey(lea_ctx *c, const u8 *key, int keybytes) {
    static const int R[6] = { 1, 3, 6, 11, 13, 17 };
    u32 T[8]; int kw = keybytes / 4;
    for (int i = 0; i < kw; i++) T[i] = le32(key + 4 * i);
    c->rounds = keybytes == 16 ? 24 : keybytes == 24 ? 28 : 32;
    for (int i = 0; i < c->rounds; i++) {
        if (keybytes == 16) {
            u32 d = DELTA[i & 3];
            T[0] = rol(T[0] + rol(d, i), 1); T[1] = rol(T[1] + rol(d, i + 1), 3);
            T[2] = rol(T[2] + rol(d, i + 2), 6); T[3] = rol(T[3] + rol(d, i + 3), 11);
            c->rk[i][0] = T[0]; c->rk[i][1] = T[1]; c->rk[i][2] = T[2]; c->rk[i][3] = T[1]; c->rk[i][4] = T[3]; c->rk[i][5] = T[1];
        } else if (keybytes == 24) {
            u32 d = DELTA[i % 6];
            for (int j = 0; j < 6; j++) { T[j] = rol(T[j] + rol(d, i + j), R[j]); c->rk[i][j] = T[j]; }
        } else {
            u32 d = DELTA[i & 7];
            for (int j = 0; j < 6; j++) {
                int idx = (6 * i + j) & 7;
                T[idx] = rol(T[idx] + rol(d, i + j), R[j]); c->rk[i][j] = T[idx];
            }
        }
    }
}
static void lea_enc(const lea_ctx *c, const u8 *in, u8 *out) {
    u32 x0 = le32(in), x1 = le32(in + 4), x2 = le32(in + 8), x3 = le32(in + 12);
    for (int i = 0; i < c->rounds; i++) {
        const u32 *k = c->rk[i];
        u32 n0 = rol((x0 ^ k[0]) + (x1 ^ k[1]), LEA_ROT_A);
        u32 n1 = ror((x1 ^ k[2]) + (x2 ^ k[3]), 5);
        u32 n2 = ror((x2 ^ k[4]) + (x3 ^ k[5]), 3);
        x3 = x0; x0 = n0; x1 = n1; x2 = n2;
    }
    put_le32(out, x0); put_le32(out + 4, x1); put_le32(out + 8, x2); put_le32(out + 12, x3);
}

int paper_main(void) {
    int groups[3] = {0, 0, 0}, goodg[3] = {0, 0, 0}, good = 0;
    for (int v = 0; v < NVEC; v++) {
        const vec *e = &VEC[v];
        u8 key[32], iv[16], pt[512], want[512], got[512];
        int kn = hexbytes(e->key, key);
        int n = hexbytes(e->pt, pt), cn = hexbytes(e->ct, want);
        if ((kn != 16 && kn != 24 && kn != 32) || n != cn || n > 400) { pstr("FAIL bad vector sizes\n"); return 1; }
        if (e->mode != 0 && hexbytes(e->iv, iv) != 16) { pstr("FAIL bad iv size\n"); return 1; }
        if (e->mode != 2 && (n & 15)) { pstr("FAIL bad message size\n"); return 1; }
        lea_ctx c; lea_setkey(&c, key, kn);
        if (e->mode == 0) {
            for (int b = 0; b < n; b += 16) lea_enc(&c, pt + b, got + b);
        } else if (e->mode == 1) {
            u8 prev[16]; for (int i = 0; i < 16; i++) prev[i] = iv[i];
            for (int b = 0; b < n; b += 16) {
                u8 t[16]; for (int i = 0; i < 16; i++) t[i] = pt[b + i] ^ prev[i];
                lea_enc(&c, t, got + b); for (int i = 0; i < 16; i++) prev[i] = got[b + i];
            }
        } else {   // CTR with a 128-bit big-endian counter block
            u8 ctr[16]; for (int i = 0; i < 16; i++) ctr[i] = iv[i];
            for (int b = 0; b < n; b += 16) {
                u8 ks[16]; lea_enc(&c, ctr, ks);
                for (int i = 0; i < 16 && b + i < n; i++) got[b + i] = pt[b + i] ^ ks[i];
                for (int i = 15; i >= 0; i--) if (++ctr[i]) break;
            }
        }
        groups[e->mode]++;
        int m = pcheck_bytes(e->name, got, want, n);
        good += m; goodg[e->mode] += m;
    }
    pstr("ECB vectors: "); pdec(goodg[0]); pstr(" of "); pdec(groups[0]); pstr(" match\n");
    pstr("CBC vectors: "); pdec(goodg[1]); pstr(" of "); pdec(groups[1]); pstr(" match\n");
    pstr("CTR vectors: "); pdec(goodg[2]); pstr(" of "); pdec(groups[2]); pstr(" match\n");
    int ok = good == NVEC;
    pstr(ok ? "PASS\n" : "FAIL\n");
    return ok ? 0 : 1;
}
